package dev.tacticalcombat.checks;

import com.google.gson.*;
import dev.tacticalcombat.character.*;
import dev.tacticalcombat.rules.*;
import dev.tacticalcombat.rules.srd.*;
import dev.tacticalcombat.uiapi.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import static dev.tacticalcombat.checks.CharacterChecks.*;
import static dev.tacticalcombat.checks.CheckService.*;

public final class CharacterCheckTests {
    private static int count;
    private static void check(boolean ok,String why){count++;if(!ok)throw new AssertionError(why);}
    private static void reject(Runnable r,String why){try{r.run();}catch(IllegalArgumentException e){count++;return;}throw new AssertionError(why);}
    public static String sheet(String clazz,int level){var s=SrdAuthoring.template();var identity=SheetSections.raw(s,"identity");identity.addProperty("characterClass",clazz);s=SheetSections.update(s,"identity",identity);var progress=SheetSections.raw(s,"progression");progress.addProperty("recordedLevel",level);s=SheetSections.update(s,"progression",progress);SrdAuthoring.data(s).addProperty("level",level);
        var skills=CreationRules.skills(clazz).stream().sorted().limit(CreationRules.skillCount(clazz)).toList();var expertise=skills.stream().limit(CreationRules.expertiseCount(clazz,level)).toList();s=SheetSections.update(s,"creation",SheetSections.JSON.toJsonTree(new CreationRules.Choices(skills,expertise,"MANUAL")).getAsJsonObject());return s.toString();}
    private static Spec spec(Key k,Mode mode,Visibility v,Set<UUID> recipients,Integer dc){return new Spec(k,mode,"Test check",v,recipients,dc);}
    public static void run()throws Exception{
        var raw=sheet("Rogue",1);var s=JsonParser.parseString(raw).getAsJsonObject();SrdAuthoring.data(s).getAsJsonObject("abilities").addProperty("str",7);raw=s.toString();
        check(keys().size()==30,"six abilities, eighteen skills, six saves");
        for(String clazz:List.of("Barbarian","Bard","Cleric","Druid","Fighter","Monk","Paladin","Ranger","Rogue","Sorcerer","Warlock","Wizard"))for(int level:List.of(1,3,5,6,10,20)){
            String fixture=sheet(clazz,level);if(clazz.equals("Bard")&&level>=10){reject(()->resolve(fixture,new Key(Category.SKILL,"Arcana")),"Bard fourth Expertise needs unsupported historical source");continue;}var choices=CreationRules.choices(JsonParser.parseString(fixture).getAsJsonObject());for(var key:keys()){var m=resolve(fixture,key);int multiple=key.category()==Category.ABILITY?0:key.category()==Category.SAVE?(CreationRules.saves(clazz).contains(key.id())?1:0):choices.expertise().contains(key.id())?2:choices.skills().contains(key.id())?1:0;check(m.multiplier()==multiple&&m.total()==m.abilityModifier()+multiple*SrdRules.proficiency(level),"exact once proficiency / expertise "+clazz+level+key);}}
        check(resolve(raw,new Key(Category.ABILITY,"str")).total()==-2,"negative modifier floors");
        for(String bad:List.of("strength","death","luck","Perceptions","str save"))reject(()->new Key(Category.SKILL,bad),"unknown skill");
        reject(()->resolve(SrdAuthoring.template().toString(),new Key(Category.SKILL,"Athletics")),"legacy provenance unavailable");
        var historical=JsonParser.parseString(raw).getAsJsonObject();var prof=SheetSections.raw(historical,"proficiencies");prof.getAsJsonArray("skills").add("Acrobatics");historical=SheetSections.update(historical,"proficiencies",prof);String history=historical.toString();reject(()->resolve(history,new Key(Category.SKILL,"Acrobatics")),"manual duplicate not promoted");check(resolve(history,new Key(Category.ABILITY,"dex")).multiplier()==0,"ordinary ability remains available");
        var mismatch=JsonParser.parseString(raw).getAsJsonObject();SrdAuthoring.data(mismatch).addProperty("level",2);reject(()->resolve(mismatch.toString(),new Key(Category.SAVE,"dex")),"level mismatch");
        var path=Files.createTempDirectory("cubetable-checks").resolve("campaigns.json");var repo=new CharacterRepository(path);var dm=new CharacterRepository.Principal(UUID.randomUUID(),true);var player=new CharacterRepository.Principal(UUID.randomUUID(),false);var other=new CharacterRepository.Principal(UUID.randomUUID(),false);var outsider=new CharacterRepository.Principal(UUID.randomUUID(),false);UUID campaign=repo.createCampaign(dm,"Checks");repo.profile(dm,campaign,repo.campaign(campaign).revision(),RulesProfiles.SRD);repo.invite(dm,campaign,repo.campaign(campaign).revision(),player.id(),false);repo.invite(dm,campaign,repo.campaign(campaign).revision(),other.id(),false);
        UUID character=repo.submit(player,campaign,RulesProfiles.SRD,raw);repo.approve(dm,character,repo.character(character).revision());repo.bind(dm,character,repo.character(character).revision(),player.id(),player.id());UUID second=repo.submit(other,campaign,RulesProfiles.SRD,sheet("Fighter",1));repo.approve(dm,second,repo.character(second).revision());repo.bind(dm,second,repo.character(second).revision(),other.id(),other.id());
        var clock=new AtomicLong(1000);var calls=new AtomicInteger();var principals=new HashMap<UUID,CharacterRepository.Principal>();for(var p:List.of(dm,player,other,outsider))principals.put(p.id(),p);
        var svc=new CheckService(repo,clock::get,()->calls.incrementAndGet()%2==1?4:17,principals::get);var ability=new Key(Category.ABILITY,"str");var own=spec(ability,Mode.NORMAL,Visibility.RECIPIENTS,Set.of(player.id()),null);long revision=repo.character(character).revision();byte[] before=Files.readAllBytes(path);var original=repo.state();
        reject(()->svc.prepare(outsider,campaign,character,revision,own,Source.PLAYER_CHARACTER_CHECK,null),"outsider rejected");reject(()->svc.prepare(other,campaign,character,revision,own,Source.PLAYER_CHARACTER_CHECK,null),"wrong controller rejected");reject(()->svc.prepare(player,campaign,character,revision+1,own,Source.PLAYER_CHARACTER_CHECK,null),"stale build rejected");reject(()->svc.prepare(player,campaign,character,revision,spec(ability,Mode.NORMAL,Visibility.CAMPAIGN,Set.of(),10),Source.PLAYER_CHARACTER_CHECK,null),"player cannot choose DM audience/DC");
        var t=svc.prepare(player,campaign,character,revision,own,Source.PLAYER_CHARACTER_CHECK,null);check(svc.prepare(player,campaign,character,revision,own,Source.PLAYER_CHARACTER_CHECK,null).equals(t),"pending mint dedup");check(calls.get()==0,"preparation never rolls");var result=svc.execute(player,campaign,t.id(),null);check(result.faces().equals(List.of(4))&&result.total()==2,"server die and negative ability");check(svc.execute(player,campaign,t.id(),null).equals(result)&&calls.get()==1,"lost ACK retry fixed");check(svc.list(other,campaign).isEmpty(),"private result absent from other inbox");check(UiEvents.SESSION.query(repo,other,campaign,0,UiEvents.Kind.CHARACTER_CHECK).events().isEmpty(),"private result absent from event history");check(UiEvents.SESSION.query(repo,player,campaign,0,UiEvents.Kind.CHARACTER_CHECK).events().size()==1,"dedup event once");
        try{result.faces().add(20);throw new AssertionError("mutable faces");}catch(UnsupportedOperationException expected){count++;}
        reject(()->svc.dismiss(player,campaign,t.id()),"accepted result cannot be dismissed");reject(()->svc.execute(player,campaign,UUID.randomUUID(),null),"client invented operation ID rejected");
        for(var mode:List.of(Mode.ADVANTAGE,Mode.DISADVANTAGE)){var a=svc.prepare(player,campaign,character,revision,spec(ability,mode,Visibility.RECIPIENTS,Set.of(player.id()),null),Source.PLAYER_CHARACTER_CHECK,null);var r=svc.execute(player,campaign,a.id(),null);check(r.faces().size()==2&&r.total()==(mode==Mode.ADVANTAGE?17:4)-2,"advantage keep "+mode);}
        var hidden=svc.prepare(dm,campaign,character,revision,spec(ability,Mode.NORMAL,Visibility.DM_ONLY,Set.of(),15),Source.DM_ADJUDICATION,null);var hr=svc.execute(dm,campaign,hidden.id(),null);check(hr.dc()==15&&hr.success()==(hr.total()>=15)&&hr.source()==Source.DM_ADJUDICATION,"DM provenance and hidden DC");check(svc.list(player,campaign).stream().noneMatch(v->v.ticket().id().equals(hidden.id())),"hidden roll absent from player inbox");
        var publicRoll=svc.prepare(dm,campaign,character,revision,spec(ability,Mode.NORMAL,Visibility.CAMPAIGN,Set.of(),15),Source.DM_ADJUDICATION,null);svc.execute(dm,campaign,publicRoll.id(),null);var publicView=svc.list(other,campaign).stream().filter(v->v.ticket().id().equals(publicRoll.id())).findFirst().orElseThrow();check(publicView.result().dc()==null&&publicView.result().success()==null&&publicView.ticket().spec().dc()==null,"public view redacts DC and success everywhere");
        var targeted=svc.prepare(dm,campaign,character,revision,spec(ability,Mode.NORMAL,Visibility.RECIPIENTS,Set.of(other.id()),14),Source.DM_ADJUDICATION,null);svc.execute(dm,campaign,targeted.id(),null);
        check(svc.list(player,campaign).stream().noneMatch(v->v.ticket().id().equals(targeted.id())),"source controller is not implicitly a targeted result recipient");
        var targetView=svc.list(other,campaign).stream().filter(v->v.ticket().id().equals(targeted.id())).findFirst().orElseThrow();check(targetView.result().version()==1&&targetView.result().dc()==null&&targetView.result().success()==null,"specific recipient gets versioned result without DC");
        check(UiEvents.SESSION.query(repo,other,campaign,0,UiEvents.Kind.CHARACTER_CHECK).events().stream().anyMatch(e->e.id().equals(targeted.id())&&e.roll().total()==targetView.result().total()),"targeted event and result share server total");
        reject(()->svc.prepare(dm,campaign,character,revision,spec(ability,Mode.NORMAL,Visibility.RECIPIENTS,Set.of(outsider.id()),null),Source.DM_ADJUDICATION,null),"nonmember recipient rejected");
        var high=new CheckService(repo,clock::get,()->20,principals::get);var nat20=high.prepare(dm,campaign,character,revision,spec(ability,Mode.NORMAL,Visibility.DM_ONLY,Set.of(),100),Source.DM_ADJUDICATION,null);check(!high.execute(dm,campaign,nat20.id(),null).success(),"natural 20 is not automatic check success");
        var low=new CheckService(repo,clock::get,()->1,principals::get);var nat1=low.prepare(dm,campaign,character,revision,spec(new Key(Category.ABILITY,"dex"),Mode.NORMAL,Visibility.DM_ONLY,Set.of(),0),Source.DM_ADJUDICATION,null);check(low.execute(dm,campaign,nat1.id(),null).success(),"natural 1 is not automatic check failure");
        var groupSpec=spec(ability,Mode.NORMAL,Visibility.DM_ONLY,Set.of(),12);var group=svc.request(dm,campaign,List.of(character,second),groupSpec,Set.of(player.id(),other.id()));check(group.size()==2&&group.get(0).group().equals(group.get(1).group()),"group request identities");check(svc.request(dm,campaign,List.of(character,second),groupSpec,Set.of(player.id(),other.id())).equals(group),"duplicate pending group no prompts");check(svc.execute(player,campaign,group.get(0).id(),null)==null,"hidden requested roll ACK contains no result");check(svc.list(dm,campaign).stream().filter(v->v.ticket().group().equals(group.get(0).group())&&v.status().equals("PENDING")).count()==1,"group partial completion");svc.dismiss(other,campaign,group.get(1).id());reject(()->svc.execute(other,campaign,group.get(1).id(),null),"dismissed ID cannot reopen");check(svc.request(dm,campaign,List.of(character,second),groupSpec,Set.of(player.id(),other.id())).equals(group),"lost group acknowledgement after all terminal answers cannot reissue prompts");
        reject(()->svc.request(player,campaign,List.of(character),groupSpec,Set.of(player.id())),"nonDM request");reject(()->svc.request(dm,campaign,List.of(character),groupSpec,Set.of()),"offline target");reject(()->svc.request(dm,campaign,List.of(character,character),groupSpec,Set.of(player.id())),"duplicate targets");
        check(repo.state()==original&&Arrays.equals(before,Files.readAllBytes(path))&&repo.state().receipts().isEmpty(),"all checks leave campaign bytes/resources/J2 receipts unchanged");
        var restarted=new CheckService(new CharacterRepository(path),clock::get,()->{throw new AssertionError("restart cannot reroll");},principals::get);reject(()->restarted.execute(player,campaign,t.id(),null),"restart rejects old IDs without RNG");check(svc.execute(player,campaign,t.id(),null).equals(result),"disconnect/reconnect same session identity retained");
        var encounterId=UUID.randomUUID();var scoped=svc.prepare(player,campaign,character,revision,own,Source.PLAYER_CHARACTER_CHECK,encounterId);reject(()->svc.execute(player,campaign,scoped.id(),UUID.randomUUID()),"stale encounter");
        clock.addAndGet(LIFETIME);reject(()->svc.execute(player,campaign,t.id(),null),"expiry never revives ID");check(UiEvents.SESSION.query(repo,player,campaign,0,UiEvents.Kind.CHARACTER_CHECK).events().isEmpty(),"expired private audit gate closes");
        for(int i=0;i<20;i++){var r=svc.prepare(player,campaign,character,revision,own,Source.PLAYER_CHARACTER_CHECK,null);svc.execute(player,campaign,r.id(),null);}reject(()->svc.prepare(player,campaign,character,revision,own,Source.PLAYER_CHARACTER_CHECK,null),"rate limit");clock.addAndGet(60_000);
        // Real persisted revocation invalidates pending, accepted history and retries.
        var pending=svc.prepare(player,campaign,character,revision,own,Source.PLAYER_CHARACTER_CHECK,null);repo.unbind(dm,player.id());reject(()->svc.execute(player,campaign,pending.id(),null),"binding revoked");check(svc.list(player,campaign).stream().noneMatch(v->v.ticket().id().equals(pending.id())),"revoked binding hides outstanding requests");
        repo.bind(dm,character,revision,player.id(),player.id());repo.invite(dm,campaign,repo.campaign(campaign).revision(),other.id(),true);var requested=svc.request(other,campaign,List.of(character),groupSpec,Set.of(player.id()));repo.revokeDm(dm,campaign,repo.campaign(campaign).revision(),other.id());reject(()->svc.execute(player,campaign,requested.get(0).id(),null),"revoked requesting DM");
        // Reassigning a character also revokes a previously accepted private result.
        clock.addAndGet(60_000);var acceptedTicket=svc.prepare(player,campaign,character,revision,own,Source.PLAYER_CHARACTER_CHECK,null);svc.execute(player,campaign,acceptedTicket.id(),null);repo.unbind(dm,player.id());repo.unbind(dm,other.id());repo.offerControl(dm,character,revision,0,other.id());repo.answerControl(other,character,repo.assignment(character).revision(),true);reject(()->svc.execute(player,campaign,acceptedTicket.id(),null),"old controller cannot retrieve accepted result");check(UiEvents.SESSION.query(repo,player,campaign,0,UiEvents.Kind.CHARACTER_CHECK).events().stream().noneMatch(e->e.id().equals(acceptedTicket.id())),"old controller cannot retrieve private audit result");
        // Exercise the actual 2048-record bound with real authorized campaign characters.
        var targets=new ArrayList<UUID>();var online=new HashSet<UUID>();targets.add(second);repo.bind(dm,second,repo.character(second).revision(),other.id(),other.id());online.add(other.id());
        for(int i=1;i<16;i++){var p=new CharacterRepository.Principal(UUID.randomUUID(),false);principals.put(p.id(),p);repo.invite(dm,campaign,repo.campaign(campaign).revision(),p.id(),false);UUID c=repo.submit(p,campaign,RulesProfiles.SRD,sheet("Fighter",1));repo.approve(dm,c,1);repo.bind(dm,c,2,p.id(),p.id());targets.add(c);online.add(p.id());}
        var bounded=new CheckService(repo,clock::get,()->10,principals::get);UUID oldest=null;for(int i=0;i<128;i++){if(i>0&&i%20==0)clock.addAndGet(60_000);var groupAtCapacity=bounded.request(dm,campaign,targets,new Spec(ability,Mode.NORMAL,"Capacity "+i,Visibility.DM_ONLY,Set.of(),null),online);if(oldest==null)oldest=groupAtCapacity.get(0).id();check(groupAtCapacity.size()==16,"bounded group slots");}
        check(bounded.list(dm,campaign).size()==CAPACITY,"real capacity filled without eviction");reject(()->bounded.request(dm,campaign,targets,new Spec(ability,Mode.NORMAL,"Overflow",Visibility.DM_ONLY,Set.of(),null),online),"capacity fails closed");UUID old=oldest;check(bounded.execute(other,campaign,old,null)==null,"oldest identity still exists at capacity and hidden result withheld");clock.addAndGet(LIFETIME);reject(()->bounded.execute(other,campaign,old,null),"evicted expired identity cannot replay");
        UiEvents.SESSION.clear();System.out.println("Authoritative character check tests passed: "+count);
    }
}
